Ltac dforall H :=
  lazymatch type of H with
  | Forall _ (_ :: _) => let A := fresh "D" in pose proof (Forall_inv H) as A; cbn [fst snd] in A;
                         apply Forall_inv_tail in H; dforall H
  | _ => clear H
  end.

